      FIN = {c:'#c7cdd0', m:0, lk:0.6, lc:'#eaf2ff', glow:'#c9dcf2', gk:0.35}, SKY = {c:'#a9bfcc', glow:'#ffe8c8', gk:0.6};
    foot(B, P, 10);
