    flat(B.p(ROOFC), offP(P, 2.5), 222);
    prism(B.p(SKY), A, 222, 223.2, false);
    const ap = [cx, 226.5, cz], oS = B.p(SKY); for (let i = 0; i < 4; i++){ const a = A[i], b = A[(i + 1) % 4]; t3(oS, [a[0], 223.2, a[1]], [b[0], 223.2, b[1]], ap); }
    for (let i = 0; i < 4; i++){ const a = A[i]; seg(B.p(MUL), [a[0], 223.2, a[1]], ap, 0.2, 3); }
