      POD = {c:'#5d6e78', m:1, fh:5.3, cw:3.0}, PODS = {c:'#c9c6bf', m:0, lk:0.35}, CAN = {c:'#b8c8cf', glow:'#fff0d8', gk:0.4}, CANF = {c:'#d8dcdc', m:0, lk:0.4};
    const R = roundP(T, 6, 4), yP = 16;
