    const pts = []; for (let i = 0; i <= 6; i++) pts.push([cx - 14 + i*28/6, i % 2 ? 9.4 : 7.6]);
    for (let i = 0; i < 6; i++){ const a = pts[i], b = pts[i + 1], za = z1, zb = z1 + 5.5;
      t3(oC, [a[0], a[1], za], [b[0], b[1], za], [b[0], b[1] + (i % 2 ? 0.8 : -0.8), zb]); t3(oC, [a[0], a[1], za], [b[0], b[1] + (i % 2 ? 0.8 : -0.8), zb], [a[0], a[1] + (i % 2 ? -0.8 : 0.8), zb]); }
    for (let i = 0; i <= 6; i += 2) seg(oF, [pts[i][0], 0.4, z1 + 4.6], [pts[i][0], pts[i][1], z1 + 4.6], 0.18, 5);
    const sp = redLights(B, g, cornersAt(T, 253.6, 4));
