// ================= medium-detail towers: one builder, a spec per key =================
// S: zh en H (architectural height) roof (main roof height) yl (lobby top) fh (floor height) gl mul ms md sp (facade specs) plan(P)
// (plan modifier) pod (podium height for the other target pieces, default their app height) crown(B, P, S, g) extra(B, P, S, g)
// lt; facade colours and crowns are estimates unless the section says otherwise.
function stdTower(key, S){
  LANDMARKS[key] = {zh:S.zh, en:S.en, cat:'new', r:S.r || 45, h:S.H, lt:S.lt || nightLt(0.6),
    build(){
      const g = new THREE.Group(), B = mkB(), E = D[key], T = S.plan ? S.plan(E.T) : E.T, H = S.H, roof = S.roof || H - 3, yl = S.yl || 9;
      foot(B, S.lowIn ? offP(T, S.lowIn) : T, yl, S.stone, S.inset);
      shaft(B, T, yl, roof, {gl:S.gl, mul:S.mul, mstep:S.ms || 3, md:S.md, mw:S.mw, sp:S.sp, fh:S.fh || 4.2, bh:S.bh || 0.5, boff:S.boff});
      if (S.crown) S.crown(B, T, S, g, roof);
      else roofTop(B, T, roof, Math.max(roof + 1.2, H), 5, Math.min(4.5, H - roof - 0.2 > 0 ? H - roof - 0.2 : 3.5));
      // the other target pieces: podium / annex blocks
      for (const [h0, R] of (E.X || [])){ const h = S.pod !== undefined ? S.pod : h0;
        prism(B.p(STONE), offP(R, -0.2), -5, 0.4);
        prism(B.p(S.podGl || {c:'#566770', m:1, fh:4.5, cw:3.0}), offP(R, 0.4), 0.4, h - 2.2, false);
        prism(B.p(S.podCap || CAP), R, h - 2.2, h, false); flat(B.p(ROOFC), R, h); }
      if (S.extra) S.extra(B, T, S, g, roof);
      const sp = redLights(B, g, S.lights ? S.lights(T, roof) : cornersAt(T, Math.max(roof + 1.2, H), 1.2));
      B.flush(g); sprites(g, sp, [1, 0.2, 0.12], 8);
      return g;
    }};
  place(key);
}
// crown helpers
// an open screen of vertical blades (0.6 m deep every bs m) round the plant floors from y0 to y1, a cap band
const screenCrown = (spec, bs) => (B, P, S, g, roof) => {
  flat(B.p(ROOFC), offP(P, 0.4), roof); prism(B.p(PLANT), offP(P, 3), roof, roof + Math.min(8, S.H - roof - 1));
  prism(B.p(S.sp || CAP), P, roof - 0.5, roof + 0.6, false);
  finsP(B.p(spec), P, roof + 0.6, S.H, bs || 1.5, 0.5, 0.14, 0.2);
  prism(B.p(spec), offP(P, -0.15), S.H - 0.9, S.H, false);
};
// stepped crown: the shaft steps in by d at each of the given heights (fractions of the rise from roof to H), glass, flat tops
const stepCrown = (gl, d, n) => (B, P, S, g, roof) => {
  let y = roof; const dy = (S.H - roof)/n;
  for (let i = 0; i < n; i++){ const Q = offP(P, d*(i + 1)); flat(B.p(ROOFC), offP(P, d*i), y); prism(B.p(gl), Q, y, y + dy - 0.6, false); prism(B.p(CAP), Q, y + dy - 0.6, y + dy, false); y += dy; }
  flat(B.p(ROOFC), offP(P, d*n), S.H);
};
const GLB = c => ({c, m:1, fh:4.2, cw:3.0});
const MULS = {c:'#cfd4d6', m:0, lk:0.3, lc:'#eaf2ff'}, SPS = {c:'#9aa4aa', m:0, lk:0.2}, MULD = {c:'#4b5257', m:0, lk:0.25}, SPD = {c:'#3f474c', m:0, lk:0.2};

