stdTower('szanlian', {zh:'安联大厦', en:'Anlian Tower', r:46, H:162, roof:158, yl:10, fh:4.9, gl:GLB('#6d8f96'), mul:MULS, ms:3, md:0.3, sp:SPS});

// ---- Southern Bosera Building (南方博时基金大厦; SBF Tower, Hans Hollein and Christoph Monschein, commissioned 2010, completed 2018) ----
// 208 m architectural height, 42 floors (CTBUH 11471). urbannext / ArchDaily: a 45 x 45 m square plan; a skirt building partly frames the
// base (entrance, business hall, restaurant); above it the tower is layered in two kinds of zone, alternating three to four times: six
// identical floors with a square outer line, and five floors whose outline changes floor by floor - deep setbacks and far-reaching
// cantilevers along an imaginary facade line, overgrown with plants (sky gardens); stone, wood, glass and metal. Footprint OSM
// w529086137 (47.5 m square). The zone sequence below (lobby 12 m, 3 x (6 + 5) floors, a last block of 6, crown to 208 m), the floor
// height (4.3 m) and the setback / cantilever pattern are estimates that follow that description; the skirt building is not on the target
// footprint (left to the app).
LANDMARKS.szbosera = {zh:'南方博时基金大厦', en:'Southern Bosera Building', cat:'new', r:40, h:208, lt:nightLt(0.6),
  build(){
    const g = new THREE.Group(), B = mkB(), P = D.szbosera.T, [x0, z0, x1, z1] = bbP(P), cx = (x0 + x1)/2, cz = (z0 + z1)/2, hw = (x1 - x0)/2, hd = (z1 - z0)/2;
    const GL = {c:'#5f727c', m:1, fh:4.3, cw:1.8}, FR = {c:'#d6d1c6', m:0, lk:0.3, lc:'#fff0dc'}, SLAB = {c:'#cbc6bb', m:0, lk:0.25},
      WOOD = {c:'#9b7a58', m:0, lk:0.3, lc:'#ffd9a8'}, PL = '#5f7f4a', PL2 = '#73944f';
    foot(B, P, 12);
    const fh = 4.3; let y = 12;
    const sq = (n) => { const y1 = y + n*fh; prism(B.p(GL), P, y, y1, false); finsP(B.p(FR), P, y, y1, 2.25, 0.45, 0.22, 0.5); bandsP(B.p(FR), P, y - fh, y1 + fh*0.5, fh, 0.7, 0.18); y = y1; };
    const sculpt = (n, seed) => {
      for (let f = 0; f < n; f++){
        // each face moves in (setback, a planted terrace in front) or out (cantilever) by up to 4.5 m, a different mix on each floor
        const off = [0, 1, 2, 3].map(i => { const v = ((seed*7 + f*3 + i*5) % 9) - 4; return v*1.1; });   // -4.4 .. +4.4 m, deterministic
        const Q = [[cx - hw - off[3], cz - hd - off[0]], [cx + hw + off[1], cz - hd - off[0]], [cx + hw + off[1], cz + hd + off[2]], [cx - hw - off[3], cz + hd + off[2]]];
        const y1 = y + fh;
        prism(B.p(GL), offP(Q, 0.6), y + 0.6, y1, false);
        prism(B.p(SLAB), Q, y, y + 0.6, false); flat(B.p(SLAB), Q, y + 0.6);
        // planted terraces where the face is set back; timber soffits where it cantilevers
        if (off.some(v => v < 0)) for (let i = 0; i < 4; i++) if (off[i] < -1){
          const P0 = P, a = P0[i], b = P0[(i + 1) % 4]; const [nx, nz] = edgeN(P0, i);
          const q = [a, b, [b[0] + nx*off[i], b[1] + nz*off[i]], [a[0] + nx*off[i], a[1] + nz*off[i]]];
          prism(B.p(f % 2 ? PL : PL2), q, y + 0.6, y + 1.5, true);
          for (let k = 0; k < 3; k++){ const t = (k + 0.5)/3, px = lerp(a[0], b[0], t) + nx*off[i]*0.5, pz = lerp(a[1], b[1], t) + nz*off[i]*0.5; obox(B.p(PL), px, pz, 0.4*k, 2.2, 2.2, y + 1.5, y + 3.2); } }
        if (off.some(v => v > 1)) flat(B.p(WOOD), Q, y + 0.02);
        y = y1;
      }
    };
    for (let z = 0; z < 3; z++){ sq(6); sculpt(5, z + 1); }
    sq(6);
    // top: a framed roof storey, plant, the crown frame to 208 m
    prism(B.p(GL), offP(P, 2), y, y + fh, false); flat(B.p(ROOFC), P, y);
    finsP(B.p(FR), P, y, y + fh, 4.5, 0.45, 0.25, 0.5);
    // open crown frame (corner posts, a blade screen, top ring) round the plant storey, to 208 m
    flat(B.p(ROOFC), offP(P, 2), y + fh); prism(B.p(PLANT), offP(P, 7), y + fh, y + fh + 6);
    for (const [px, pz] of P) abox(B.p(FR), px - 1.4, px + 1.4, y + fh, 208, pz - 1.4, pz + 1.4);
    finsP(B.p(FR), P, y + fh, 206.6, 2.25, 0.4, 0.12, 2);
    prism(B.p(FR), offP(P, -0.3), 206.6, 208, false); prism(B.p(FR), offP(P, 1.2), 206.6, 208, false); prism(B.p(FR), offP(P, -0.3), y + fh, y + fh + 1.2, false);
    const sp = redLights(B, g, cornersAt(P, 208, 1));
    B.flush(g); sprites(g, sp, [1, 0.2, 0.12], 8);
    return g;
  }};
place('szbosera');

