// ---- Essence Financial Securities Headquarters (安信金融大厦; Rocco Design Architects Associates, completed 2021-23), 193.5 m, 39 floors
// (CTBUH 15039). Archinect / Domus: the main body is lifted to open a pedestrian passage from the entrance plaza; a twin-side core and an
// exoskeleton stiffened by horizontal trusses free the floor centres for triple- and seven-storey internal courtyards in the three upper
// stacks of floors; a green-walled volume at the base. OSM w612997283 (height 181.5 = the roof), 47 x 42 m. Modelled: the two side cores
// as solid bands on the east and west faces running to the ground, the lifted glass body above a 12 m open passage, horizontal truss
// belts dividing the stacks (their levels are estimates), the crown frame to 193.5 m.
stdTower('szessence', {zh:'安信金融大厦', en:'Essence Financial Securities Headquarters', r:38, H:193.5, roof:181.5, yl:12, fh:4.3,
  gl:GLB('#6b8290'), mul:MULS, ms:2.0, md:0.3, sp:SPS, inset:6,
  crown:(B, P, S, g, roof) => { roofTop(B, P, roof, roof + 1.2, 4, 4); const [x0, z0, x1, z1] = bbP(P), o = B.p({c:'#9aa3a8', m:0, lk:0.5, lc:'#eaf2ff'});
    // the exoskeleton rises past the roof as an open frame: posts every ~9.4 m on the long faces, a top truss band
    for (const z of [z0, z1]) for (let k = 0; k <= 5; k++){ const x = lerp(x0, x1, k/5); abox(o, x - 0.5, x + 0.5, roof, 193.5, z - 0.5, z + 0.5); }
    prism(o, rectP(x0, z0, x1, z1), 190.5, 193.5, false); prism(o, rectP(x0 + 0.8, z0 + 0.8, x1 - 0.8, z1 - 0.8), 190.5, 193.5, false); },
  extra:(B, P, S, g, roof) => { const [x0, z0, x1, z1] = bbP(P), CORE = {c:'#8f979b', m:0, lk:0.3}, TR = {c:'#a7aeb2', m:0, lk:0.45, lc:'#eaf2ff'};
    // side cores (8 m wide bands on the short west and east faces), down to the ground
    abox(B.p(CORE), x0 - 0.6, x0 + 7, -5, roof + 1.2, z0 + 9, z1 - 9); abox(B.p(CORE), x1 - 7, x1 + 0.6, -5, roof + 1.2, z0 + 9, z1 - 9);
    // horizontal truss belts (3 m) with diagonals on the long faces, splitting the body into stacks
    for (const yb of [12, 58, 104, 145]){ for (const z of [z0 - 0.5, z1 + 0.5]){ abox(B.p(TR), x0, x1, yb, yb + 0.8, z - 0.3, z + 0.3); abox(B.p(TR), x0, x1, yb + 3.2, yb + 4, z - 0.3, z + 0.3);
      for (let k = 0; k < 6; k++){ const xa = lerp(x0 + 7, x1 - 7, k/6), xb = lerp(x0 + 7, x1 - 7, (k + 1)/6); seg(B.p(TR), [xa, yb + 0.8, z], [xb, yb + 3.2, z], 0.25, 4); } } }
    // the green-walled base volume is not on this footprint (left to the app)
  }});

