// ---- Shenzhen Guosen Securities Tower (国信金融大厦; Studio Fuksas with SADI, competition 2011, built 2015-2019), 228 m, 50 floors
// (CTBUH 10258). designboom: "a three-dimensional void that stretches the full height of the tower" (a vertical piazza linking the lobby
// on 1, a lobby on the west facade at 12, one on the east facade at 27 and the roof garden at 43); the glass envelope "as rational as
// possible". OSM w612997276, 43.5 x 45 m. Modelled: a rational glass prism with the void as a deep glazed slot up the west face from 12 m
// and up the east face from 27 m to the roof garden (the slot positions and width are estimates).
stdTower('szguosen', {zh:'国信金融大厦', en:'Guosen Securities Tower', r:38, H:228, roof:224.5, yl:12, fh:4.3,
  gl:GLB('#728c9a'), mul:MULS, ms:1.5, md:0.25, mw:0.07, sp:SPS, bh:0.3,
  extra:(B, P, S, g, roof) => { const [x0, z0, x1, z1] = bbP(P), V = {c:'#3f4c55', m:1, fh:4.3, cw:3, glow:'#ffe6c4', gk:0.25}, Fr = {c:'#e1e4e5', m:0, lk:0.4};
    // the void: a recessed, darker glazed slot (6 m deep, 9 m wide) on the west face from 12 m and the east face from 27 m to the roof
    for (const [x, sg, y0] of [[x0, 1, 12 + 4.3*11], [x1, -1, 12 + 4.3*26]]){ const zc = (z0 + z1)/2, xa = x - sg*0.3, xb = x + sg*6;
      prism(B.p(V), rectP(Math.min(xa, xb), zc - 4.5, Math.max(xa, xb), zc + 4.5), y0, roof, false);
      abox(B.p(Fr), Math.min(xa, xb), Math.max(xa, xb), y0 - 0.6, y0, zc - 4.8, zc + 4.8); }
    for (const [x, z] of [[x0 + 6, z0 + 6], [x1 - 6, z1 - 6], [x0 + 8, z1 - 7]]) obox(B.p(GREEN), x, z, 0, 5, 5, roof + 1.25, roof + 2);
  }});

